{"command": "mkdir -p /tmp/gotest && cd /tmp/gotest && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	srcs := []string{
		"package main\n\nfunc a() {\n} // trailing a\n// doc for x\nvar x = 1\n",
		"package main\n\nfunc a() {\n}\n// standalone\nvar x = 1\n",
		"package main\n\nvar x = 1 // trailing x\nvar y = 2\n",
		"package main\n\nfunc b() {\n} // trailing b\nfunc c() {\n}\n",
		"package main\n\ntype T struct {\n\tX int\n} // trailing T\nvar y = 2\n",
		"package main\n\nfunc a() {\n\t// inner\n}\nfunc b() {\n}\n",
	}
	for i, src := range srcs {
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, "t.go", src, parser.ParseComments)
		if err != nil { fmt.Println("ERR", err); continue }
		fmt.Printf("=== case %d\n", i)
		for _, d := range f.Decls {
			switch dd := d.(type) {
			case *ast.FuncDecl:
				fmt.Printf("  Func %s Pos=%v End=%v Comment=%v Doc=%v\n", dd.Name.Name, fset.Position(dd.Pos()), fset.Position(dd.End()), dd.Comment, dd.Doc)
			case *ast.GenDecl:
				fmt.Printf("  Gen %s Pos=%v End=%v\n", dd.Tok, fset.Position(dd.Pos()), fset.Position(dd.End()))
				for _, s := range dd.Specs {
					switch ss := s.(type) {
					case *ast.ValueSpec:
						fmt.Printf("    Val %v Pos=%v End=%v Comment=%v Doc=%v\n", ss.Names, fset.Position(ss.Pos()), fset.Position(ss.End()), ss.Comment, ss.Doc)
					case *ast.TypeSpec:
						fmt.Printf("    Type %s Pos=%v End=%v Comment=%v Doc=%v\n", ss.Name.Name, fset.Position(ss.Pos()), fset.Position(ss.End()), ss.Comment, ss.Doc)
					case *ast.ImportSpec:
						fmt.Printf("    Imp %v Pos=%v End=%v Comment=%v Doc=%v\n", ss.Path, fset.Position(ss.Pos()), fset.Position(ss.End()), ss.Comment, ss.Doc)
					}
				}
			}
		}
		fmt.Printf("  comments: %v\n", f.Comments)
	}
}
EOF
go run main.go 2>&1 | head -60"}

