{"command": "cd /tmp/gotest && cat > main2.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	srcs := []string{
		"package main\n\nimport \"fmt\" // X\n\nfunc f() {}\n",
		"package main\n\nimport \"fmt\"// X\n\nfunc f() {}\n",
		"package main\n\nimport \"fmt\"\t// X\n\nfunc f() {}\n",
		"package main\n\nimport (\n\t\"fmt\" // X\n)\n\nfunc f() {}\n",
	}
	for i, src := range srcs {
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, "t.go", src, parser.ParseComments)
		if err != nil { fmt.Println("ERR", err); continue }
		for _, d := range f.Decls {
			gd, ok := d.(*ast.GenDecl)
			if !ok { continue }
			for _, s := range gd.Specs {
				imp := s.(*ast.ImportSpec)
				fmt.Printf("case %d: spec.End=%v Comment=%v Comment.Text=%q spec.Text=%q\n", i, fset.Position(imp.End()), imp.Comment, imp.Comment.Text, fset.Position(imp.Pos()))
			}
		}
	}
}
EOF
go run main2.go"}

