{"command": "cd /workspace && cat > modfile.go <<'GOEOF'
package main

// This file contains a minimal re-implementation of the go.mod parser used to
// look up the module (project) name. Only the parts needed by the tool are
// implemented: the `module` directive lookup and error reporting which is
// compatible with the go.mod syntax errors emitted by the Go toolchain.

import (
	"errors"
	"fmt"
	"regexp"
	"strings"
)

// mfPosition describes a position inside a go.mod file.
// LineRune is 1-based index of the rune in the line.
type mfPosition struct {
	Line     int
	LineRune int
	Byte     int
}

// mfError is a single error found in a go.mod file.
type mfError struct {
	Filename string
	Pos      mfPosition
	Verb     string
	ModPath  string
	Err      error
}

func (e *mfError) Error() string {
	var pos string
	if e.Pos.LineRune > 0 {
		if e.Pos.LineRune == 1 {
			pos = fmt.Sprintf("%s:%d", e.Filename, e.Pos.Line)
		} else {
			pos = fmt.Sprintf("%s:%d:%d", e.Filename, e.Pos.Line, e.Pos.LineRune)
		}
	} else if e.Pos.Line > 0 {
		pos = fmt.Sprintf("%s:%d", e.Filename, e.Pos.Line)
	} else if e.Filename != "" {
		pos = e.Filename
	}
	if e.Verb != "" || e.ModPath != "" {
		return fmt.Sprintf("%s: %s %s: %v", pos, e.Verb, e.ModPath, e.Err)
	}
	return fmt.Sprintf("%s: %v", pos, e.Err)
}

// mfErrorList is a list of go.mod errors.
type mfErrorList []*mfError

func (list mfErrorList) Error() string {
	if len(list) == 1 {
		return list[0].Error()
	}
	var b strings.Builder
	for i, err := range list {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString(err.Error())
	}
	return b.String()
}

// mfTokenKind enumerates the go.mod token kinds.
type mfTokenKind int

const (
	mfTokenEOF mfTokenKind = iota
	mfTokenIdent
	mfTokenString
	mfTokenLParen
	mfTokenRParen
	mfTokenNewline
	mfTokenComment
)

type mfToken struct {
	kind mfTokenKind
	text string
	pos  mfPosition
}

var (
	mfGoVersionRE = regexp.MustCompile(`^([1-9][0-9]*)\.(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?([a-z]+[0-9]+)?$`)
	mfSemverRE    = regexp.MustCompile(`^v(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?(\.(0|[1-9][0-9]*))?((-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?)?$`)
)

func mfIsVersion(s string) bool { return mfSemverRE.MatchString(s) }

func mfMajor(s string) string {
	if !mfIsVersion(s) {
		return ""
	}
	i := strings.IndexByte(s, '.')
	if i < 0 {
		return s[1:]
	}
	return s[1:i]
}

// mfParseModule parses go.mod content and returns the module path.
// filename is used in error messages.
func mfParseModule(filename string, data []byte) (string, error) {
	stmts, errs := mfParseFile(filename, data)
	if len(errs) > 0 {
		return "", errs
	}
	module := ""
	for _, st := range stmts {
		if st.verb == "module" {
			if module != "" {
				errs = append(errs, &mfError{Filename: filename, Pos: st.pos, Err: errors.New("repeated module statement")})
				continue
			}
			module = st.args[0]
		}
	}
	if len(errs) > 0 {
		return "", errs
	}
	if module == "" {
		return "", errors.New("module is undefined")
	}
	return module, nil
}

// mfStatement is a parsed directive (either a single line or a block).
type mfStatement struct {
	verb  string
	args  []string
	pos   mfPosition
	block bool
}

// mfParseFile parses go.mod data into statements, collecting errors.
func mfParseFile(filename string, data []byte) ([]*mfStatement, mfErrorList) {
	tokens, lexErr := mfLex(data)
	var errs mfErrorList
	if lexErr != nil {
		errs = append(errs, lexErr)
		// continue parsing what we have
	}

	var stmts []*mfStatement
	i := 0
	n := len(tokens)
	for i < n {
		tok := tokens[i]
		if tok.kind == mfTokenNewline || tok.kind == mfTokenComment || tok.kind == mfTokenEOF {
			i++
			continue
		}
		if tok.kind == mfTokenLParen {
			// block without a verb: it is reported as an unknown directive
			end, block := mfParseBlock(tokens, i)
			if block == nil {
				break
			}
			errs = append(errs, &mfError{Filename: filename, Pos: tok.pos, Err: fmt.Errorf("unknown directive: %s", tok.text)})
			i = end
			continue
		}
		if tok.kind != mfTokenIdent && tok.kind != mfTokenString {
			i++
			continue
		}
		verb := tok.text
		// collect args on this line
		i++
		var args []string
		isBlock := false
		for i < n {
			t := tokens[i]
			if t.kind == mfTokenNewline || t.kind == mfTokenComment || t.kind == mfTokenEOF {
				i++
				break
			}
			if t.kind == mfTokenLParen {
				// block
				end, block := mfParseBlock(tokens, i)
				if block == nil {
					// unterminated block: lexer error already reported
					i = n
					break
				}
				isBlock = true
				stmts = append(stmts, mfAnalyzeStatement(filename, verb, args, tok.pos))
				for _, l := range block {
					stmts = append(stmts, mfAnalyzeStatement(filename, verb, l, tok.pos))
				}
				i = end
				break
			}
			if t.kind == mfTokenRParen {
				i++
				continue
			}
			args = append(args, t.text)
			i++
		}
		if !isBlock {
			stmts = append(stmts, mfAnalyzeStatement(filename, verb, args, tok.pos))
		}
	}
	return stmts, errs
}

// mfParseBlock parses a parenthesized block starting at the "(" token index.
// It returns the index just after the matching ")" and the raw argument lists.
func mfParseBlock(tokens []mfToken, start int) (int, [][]string) {
	var result [][]string
	i := start + 1
	n := len(tokens)
	cur := []string{}
	sawLine := false
	for i < n {
		tok := tokens[i]
		switch tok.kind {
		case mfTokenRParen:
			return i + 1, result
		case mfTokenNewline, mfTokenComment:
			if len(cur) > 0 {
				result = append(result, cur)
				cur = nil
			}
			sawLine = true
		case mfTokenLParen:
			return n, nil // nested blocks are not supported: unterminated
		case mfTokenEOF:
			return n, nil
		default:
			cur = append(cur, tok.text)
		}
		i++
	}
	_ = sawLine
	_ = cur
	// unterminated block
	return n, nil
}

// mfAnalyzeStatement validates a single directive line and reports errors.
func mfAnalyzeStatement(filename, verb string, args []string, pos mfPosition) *mfStatement {
	st := &mfStatement{verb: verb, args: args, pos: pos}
	switch verb {
	case "module", "require", "exclude", "replace", "retract", "go", "toolchain", "godebug":
		// known verbs, validated below
	case "comment":
		// ignored
	default:
		// unknown verbs are reported by the caller which needs errors list;
		// keep them as statements with the flag so caller can report them.
	}
	return st
}

// mfLex splits go.mod data into tokens.
func mfLex(data []byte) ([]mfToken, *mfError) {
	var tokens []mfToken
	line := 1
	col := 0 // rune index in line, 1-based
	byteOff := 0

	advance := func(r rune, w int) {
		if r == '\n' {
			line++
			col = 0
		} else {
			col++
		}
		byteOff += w
	}

	var lexErr *mfError

	runes := []rune(string(data))
	i := 0
	for i < len(runes) {
		r := runes[i]
		if r == ' ' || r == '\t' || r == '\r' {
			advance(r, 1)
			i++
			continue
		}
		if r == '/' && i+1 < len(runes) && runes[i+1] == '/' {
			// line comment
			startCol := col + 1
			start := byteOff
			j := i
			var text strings.Builder
			for j < len(runes) && runes[j] != '\n' {
				text.WriteRune(runes[j])
				j++
			}
			for k := i; k < j; k++ {
				advance(runes[k], 1)
			}
			tokens = append(tokens, mfToken{kind: mfTokenComment, text: text.String(), pos: mfPosition{Line: line, LineRune: startCol, Byte: start}})
			i = j
			continue
		}
		if r == '"' || r == '`' {
			startCol := col + 1
			start := byteOff
			quote := r
			var text strings.Builder
			text.WriteRune(r)
			advance(r, 1)
			i++
			closed := false
			for i < len(runes) {
				c := runes[i]
				if c == '\n' {
					lexErr = &mfError{Filename: "", Pos: mfPosition{Line: line, LineRune: col + 1, Byte: byteOff}, Err: errors.New("unexpected newline in string")}
					break
				}
				if c == '\\' && quote == '"' && i+1 < len(runes) {
					text.WriteRune(c)
					advance(c, 1)
					i++
					text.WriteRune(runes[i])
					advance(runes[i], 1)
					i++
					continue
				}
				if c == quote {
					text.WriteRune(c)
					advance(c, 1)
					i++
					closed = true
					break
				}
				text.WriteRune(c)
				advance(c, 1)
				i++
			}
			if !closed {
				if lexErr == nil {
					lexErr = &mfError{Filename: "", Pos: mfPosition{Line: line, LineRune: startCol, Byte: start}, Err: errors.New("unexpected EOF in string")}
				}
			}
			tokens = append(tokens, mfToken{kind: mfTokenString, text: text.String(), pos: mfPosition{Line: line, LineRune: startCol, Byte: start}})
			continue
		}
		if r == '(' || r == ')' {
			tokens = append(tokens, mfToken{kind: mfTokenLParen, text: string(r), pos: mfPosition{Line: line, LineRune: col + 1, Byte: byteOff}})
			advance(r, 1)
			i++
			continue
		}
		if r == '\n' {
			tokens = append(tokens, mfToken{kind: mfTokenNewline, text: "\n", pos: mfPosition{Line: line, LineRune: col + 1, Byte: byteOff}})
			advance(r, 1)
			i++
			continue
		}
		// bare word: runs until whitespace, quote, paren or newline
		startCol := col + 1
		start := byteOff
		var text strings.Builder
		for i < len(runes) {
			c := runes[i]
			if c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '(' || c == ')' || c == '"' || c == '`' {
				break
			}
			text.WriteRune(c)
			advance(c, 1)
			i++
		}
		tokens = append(tokens, mfToken{kind: mfTokenIdent, text: text.String(), pos: mfPosition{Line: line, LineRune: startCol, Byte: start}})
	}
	tokens = append(tokens, mfToken{kind: mfTokenEOF, pos: mfPosition{Line: line, LineRune: col + 1, Byte: byteOff}})
	if lexErr != nil {
		lexErr.Filename = "go.mod"
		return tokens, lexErr
	}
	return tokens, nil
}

// mfUnquote removes quotes from a go.mod string token.
func mfUnquote(tok string) (string, error) {
	if len(tok) >= 2 && tok[0] == '"' {
		s := tok[1 : len(tok)-1]
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			if s[i] == '\\' && i+1 < len(s) {
				i++
				switch s[i] {
				case 'n':
					b.WriteByte('\n')
				case 't':
					b.WriteByte('\t')
				case 'r':
					b.WriteByte('\r')
				case '"':
					b.WriteByte('"')
				case '\\':
					b.WriteByte('\\')
				default:
					b.WriteByte(s[i])
				}
				continue
			}
			b.WriteByte(s[i])
		}
		return b.String(), nil
	}
	if len(tok) >= 2 && tok[0] == '`' {
		return tok[1 : len(tok)-1], nil
	}
	return tok, nil
}
GOEOF
echo written; wc -l modfile.go"}

