	case "require", "exclude":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "replace":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "retract":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "toolchain", "godebug":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
