			wrap(errors.New("replacement module without version must be directory path (rooted or starting with . or ..)"))
			return
		}
	}
}

func filepathIsAbs(p string) bool {
	return len(p) > 0 && p[0] == '/'
}

// mfUnquote removes quotes from a go.mod string token.
func mfUnquote(tok string) (string, error) {
	if len(tok) >= 2 && tok[0] == '"' {
		s := tok[1 : len(tok)-1]
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			if s[i] == '\\' && i+1 < len(s) {
				i++
				switch s[i] {
				case 'n':
					b.WriteByte('\n')
				case 't':
					b.WriteByte('\t')
				case 'r':
					b.WriteByte('\r')
				case '"':
					b.WriteByte('"')
				case '\\':
					b.WriteByte('\\')
				default:
					b.WriteByte(s[i])
				}
				continue
			}
			b.WriteByte(s[i])
		}
		return b.String(), nil
	}
	if len(tok) >= 2 && tok[0] == '`' {
		return tok[1 : len(tok)-1], nil
	}
	return tok, nil
}

// mfLex splits go.mod data into tokens with positions.
func mfLex(data []byte) ([]mfToken, *mfError) {
	var tokens []mfToken
	line := 1
	col := 0 // rune index in the current line, 0-based
	var lexErr *mfError

	runes := []rune(string(data))
	i := 0
	for i < len(runes) {
		r := runes[i]
		if r == ' ' || r == '\t' || r == '\r' {
			col++
			i++
			continue
		}
		if r == '/' && i+1 < len(runes) && runes[i+1] == '/' {
			startCol := col + 1
			j := i
			var text strings.Builder
			for j < len(runes) && runes[j] != '\n' {
				text.WriteRune(runes[j])
				j++
			}
			col += j - i
			i = j
			tokens = append(tokens, mfToken{kind: mfTokenComment, text: text.String(), line: line, col: startCol})
			continue
		}
		if r == '"' || r == '`' {
			startCol := col + 1
			quote := r
			var text strings.Builder
			text.WriteRune(r)
			col++
			i++
			closed := false
			for i < len(runes) {
				c := runes[i]
				if c == '\n' {
					lexErr = &mfError{Pos: mfPosition{Line: line, LineRune: col + 1}, Err: errors.New("unexpected newline in string")}
					break
				}
				if c == '\\' && quote == '"' && i+1 < len(runes) {
					text.WriteRune(c)
					col++
					i++
					text.WriteRune(runes[i])
					col++
					i++
					continue
				}
				text.WriteRune(c)
				col++
				i++
				if c == quote {
					closed = true
					break
				}
			}
			if !closed && lexErr == nil {
				lexErr = &mfError{Pos: mfPosition{Line: line, LineRune: startCol}, Err: errors.New("unexpected EOF in string")}
			}
			tokens = append(tokens, mfToken{kind: mfTokenString, text: text.String(), line: line, col: startCol})
			continue
		}
		if r == '\n' {
			tokens = append(tokens, mfToken{kind: mfTokenNewline, text: "\n", line: line, col: col + 1})
			line++
			col = 0
			i++
			continue
		}
		if r == '(' || r == ')' {
			tokens = append(tokens, mfToken{kind: mfTokenLParen, text: string(r), line: line, col: col + 1})
			col++
			i++
			continue
		}
		startCol := col + 1
		var text strings.Builder
		for i < len(runes) {
			c := runes[i]
			if c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '(' || c == ')' || c == '"' || c == '`' {
				break
			}
			text.WriteRune(c)
			col++
			i++
		}
		tokens = append(tokens, mfToken{kind: mfTokenIdent, text: text.String(), line: line, col: startCol})
	}
	tokens = append(tokens, mfToken{kind: mfTokenEOF, line: line, col: col + 1})
	return tokens, lexErr
}
