		mfValidateLine(&errs, filename, verb, lineArgs, linePos, &moduleDefined, &goDefined, &modulePath)
	}

	if len(errs) > 0 {
		return "", errs
	}
	if !moduleDefined {
		return "", errors.New("module is undefined")
	}
	return modulePath, nil
}

func mfPos(t mfToken) mfPosition { return mfPosition{Line: t.line, LineRune: t.col} }

// mfReadBlock reads the lines of a parenthesized block starting after "(".
func mfReadBlock(tokens []mfToken, start int) ([][]string, int) {
	var result [][]string
	i := start
	n := len(tokens)
	cur := []string{}
	for i < n {
		tok := tokens[i]
		switch tok.kind {
		case mfTokenRParen:
			if len(cur) > 0 {
				result = append(result, cur)
			}
			return result, i + 1
		case mfTokenNewline, mfTokenComment:
			if len(cur) > 0 {
				result = append(result, cur)
				cur = nil
			}
		case mfTokenEOF:
			return nil, n
		case mfTokenLParen:
			return nil, n
		default:
			cur = append(cur, tok.text)
		}
		i++
	}
	return nil, n
}

func mfSkipBlock(tokens []mfToken, start int) int {
	i := start
	n := len(tokens)
	for i < n {
		if tokens[i].kind == mfTokenRParen {
			return i + 1
		}
		if tokens[i].kind == mfTokenEOF {
			return n
		}
		i++
	}
	return n
}

func mfValidateBlock(errs *mfErrorList, filename, verb string, headArgs []string, blockArgs [][]string, pos mfPosition) {
	switch verb {
	case "module":
		for _, args := range blockArgs {
			mfValidateLine(errs, filename, verb, append(append([]string{}, headArgs...), args...), pos, new(bool), new(bool), new(string))
		}
	case "require", "exclude":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "replace":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "retract":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	case "toolchain", "godebug":
		for _, args := range blockArgs {
			mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
		}
	default:
		*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: fmt.Errorf("unknown block type: %s", verb)})
	}
}

func mfValidateLine(errs *mfErrorList, filename, verb string, args []string, pos mfPosition, moduleDefined, goDefined *bool, modulePath *string) {
	switch verb {
	case "module":
		if *moduleDefined {
			*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: errors.New("repeated module statement")})
			return
		}
		if len(args) != 1 {
			*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: errors.New("usage: module module/path")})
			return
		}
		s, err := mfUnquote(args[0])
		if err != nil {
			*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: fmt.Errorf("invalid quoted string: %v", err)})
			return
		}
		*moduleDefined = true
		*modulePath = s
	case "go":
		if *goDefined {
			*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: errors.New("repeated go statement")})
			return
		}
		mfValidateVerb(errs, filename, verb, args, pos, goDefined, nil, nil)
		*goDefined = true
	default:
		mfValidateVerb(errs, filename, verb, args, pos, nil, nil, nil)
	}
}

func mfValidateVerb(errs *mfErrorList, filename, verb string, args []string, pos mfPosition, goDefined *bool, _, _ *bool) {
	wrap := func(err error) {
		*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Err: err})
	}
	wrapVer := func(err error, modPath string) {
		*errs = append(*errs, &mfError{Filename: filename, Pos: pos, Verb: verb, ModPath: modPath, Err: err})
	}
	switch verb {
	default:
		wrap(fmt.Errorf("unknown directive: %s", verb))
	case "go":
		if len(args) != 1 {
			wrap(errors.New("go directive expects exactly one argument"))
			return
		}
		s, err := mfUnquote(args[0])
		if err != nil {
			wrap(fmt.Errorf("invalid quoted string: %v", err))
			return
		}
		if !mfGoVersionRE.MatchString(s) {
			wrap(fmt.Errorf("invalid go version '%s': must match format 1.23.0", s))
			return
		}
	case "toolchain":
		if len(args) != 1 {
			wrap(errors.New("toolchain directive expects exactly one argument"))
			return
		}
	case "godebug":
		if len(args) != 1 {
			wrap(errors.New("usage: godebug key=value"))
			return
		}
	case "retract":
		if len(args) == 0 {
			wrap(errors.New("expected '[' or version"))
			return
		}
	case "require", "exclude":
		if len(args) != 2 {
			wrap(fmt.Errorf("usage: %s module/path v1.2.3", verb))
			return
		}
		s, err := mfUnquote(args[0])
		if err != nil {
			wrapVer(fmt.Errorf("invalid quoted string: %v", err), "")
			return
		}
		if err := mfValidVersion(args[1]); err != nil {
			wrapVer(err, s)
			return
		}
	case "replace":
		if len(args) != 3 && len(args) != 4 {
			wrap(errors.New("usage: replace module/path [v1.2.3] => other/module v1.4"))
			return
		}
		// old [vX] => new [vY]
		old := args[0]
		var oldVersion string
		idx := 1
		if args[idx] != "=>" {
			oldVersion = args[idx]
			idx++
		}
		if idx >= len(args) || args[idx] != "=>" {
			wrap(errors.New("usage: replace module/path [v1.2.3] => other/module v1.4"))
			return
		}
		idx++
		if idx >= len(args) {
			wrap(errors.New("usage: replace module/path [v1.2.3] => other/module v1.4"))
			return
		}
		if oldVersion != "" {
			if err := mfValidVersion(oldVersion); err != nil {
				wrapVer(err, old)
				return
			}
		}
		newModule := args[idx]
		var newVersion string
		if idx+1 < len(args) {
			newVersion = args[idx+1]
		}
		if newVersion != "" {
			if err := mfValidVersion(newVersion); err != nil {
				wrapVer(err, newModule)
				return
			}
		} else if !strings.HasPrefix(newModule, "./") && !strings.HasPrefix(newModule, "../") &&
			!strings.HasPrefix(newModule, "/") && !filepathIsAbs(newModule) {
			wrap(errors.New("replacement module without version must be directory path (rooted or starting with . or ..)"))
			return
		}
	}
}

func filepathIsAbs(p string) bool {
	return len(p) > 0 && p[0] == '/'
}

// mfUnquote removes quotes from a go.mod string token.
func mfUnquote(tok string) (string, error) {
	if len(tok) >= 2 && tok[0] == '"' {
		s := tok[1 : len(tok)-1]
		var b strings.Builder
		for i := 0; i < len(s); i++ {
			if s[i] == '\\' && i+1 < len(s) {
				i++
				switch s[i] {
				case 'n':
					b.WriteByte('\n')
				case 't':
					b.WriteByte('\t')
				case 'r':
					b.WriteByte('\r')
				case '"':
					b.WriteByte('"')
				case '\\':
					b.WriteByte('\\')
				default:
					b.WriteByte(s[i])
				}
				continue
			}
			b.WriteByte(s[i])
		}
		return b.String(), nil
	}
	if len(tok) >= 2 && tok[0] == '`' {
		return tok[1 : len(tok)-1], nil
	}
	return tok, nil
}

// mfLex splits go.mod data into tokens with positions.
func mfLex(data []byte) ([]mfToken, *mfError) {
	var tokens []mfToken
	line := 1
	col := 0 // rune index in the current line, 0-based
	var lexErr *mfError

	runes := []rune(string(data))
	i := 0
	for i < len(runes) {
		r := runes[i]
		if r == ' ' || r == '\t' || r == '\r' {
			col++
			i++
			continue
		}
		if r == '/' && i+1 < len(runes) && runes[i+1] == '/' {
			startCol := col + 1
			j := i
			var text strings.Builder
			for j < len(runes) && runes[j] != '\n' {
				text.WriteRune(runes[j])
				j++
			}
			col += j - i
			i = j
			tokens = append(tokens, mfToken{kind: mfTokenComment, text: text.String(), line: line, col: startCol})
			continue
		}
		if r == '"' || r == '`' {
			startCol := col + 1
			quote := r
			var text strings.Builder
			text.WriteRune(r)
			col++
			i++
			closed := false
			for i < len(runes) {
				c := runes[i]
				if c == '\n' {
					lexErr = &mfError{Pos: mfPosition{Line: line, LineRune: col + 1}, Err: errors.New("unexpected newline in string")}
					break
				}
				if c == '\\' && quote == '"' && i+1 < len(runes) {
					text.WriteRune(c)
					col++
					i++
					text.WriteRune(runes[i])
					col++
					i++
					continue
				}
				text.WriteRune(c)
				col++
				i++
				if c == quote {
					closed = true
					break
				}
			}
			if !closed && lexErr == nil {
				lexErr = &mfError{Pos: mfPosition{Line: line, LineRune: startCol}, Err: errors.New("unexpected EOF in string")}
			}
			tokens = append(tokens, mfToken{kind: mfTokenString, text: text.String(), line: line, col: startCol})
			continue
		}
		if r == '\n' {
			tokens = append(tokens, mfToken{kind: mfTokenNewline, text: "\n", line: line, col: col + 1})
			line++
			col = 0
			i++
			continue
		}
		if r == '(' || r == ')' {
			tokens = append(tokens, mfToken{kind: mfTokenLParen, text: string(r), line: line, col: col + 1})
			col++
			i++
			continue
		}
		startCol := col + 1
		var text strings.Builder
		for i < len(runes) {
			c := runes[i]
			if c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '(' || c == ')' || c == '"' || c == '`' {
				break
			}
			text.WriteRune(c)
			col++
			i++
		}
		tokens = append(tokens, mfToken{kind: mfTokenIdent, text: text.String(), line: line, col: startCol})
	}
	tokens = append(tokens, mfToken{kind: mfTokenEOF, line: line, col: col + 1})
	return tokens, lexErr
}
