package main

// Minimal go.mod parser used to look up the project (module) name. The syntax
// handling and error messages follow the ones produced by the Go toolchain for
// malformed go.mod files.

import (
	"errors"
	"fmt"
	"regexp"
	"strings"
)

// mfPosition describes a position inside a go.mod file.
type mfPosition struct {
	Line     int
	LineRune int
}

type mfError struct {
	Filename string
	Pos      mfPosition
	Verb     string
	ModPath  string
	Err      error
}

func (e *mfError) Error() string {
	var pos string
	switch {
	case e.Pos.LineRune > 1:
		pos = fmt.Sprintf("%s:%d:%d", e.Filename, e.Pos.Line, e.Pos.LineRune)
	case e.Pos.LineRune == 1:
		pos = fmt.Sprintf("%s:%d", e.Filename, e.Pos.Line)
	case e.Pos.Line > 0:
		pos = fmt.Sprintf("%s:%d", e.Filename, e.Pos.Line)
	case e.Filename != "":
		pos = e.Filename
	}
	if e.Verb != "" || e.ModPath != "" {
		return fmt.Sprintf("%s: %s %s: %v", pos, e.Verb, e.ModPath, e.Err)
	}
	return fmt.Sprintf("%s: %v", pos, e.Err)
}

type mfErrorList []*mfError

func (list mfErrorList) Error() string {
	if len(list) == 1 {
		return list[0].Error()
	}
	var b strings.Builder
	for i, err := range list {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString(err.Error())
	}
	return b.String()
}

type mfTokenKind int

const (
	mfTokenEOF mfTokenKind = iota
	mfTokenIdent
	mfTokenString
	mfTokenLParen
	mfTokenRParen
	mfTokenNewline
	mfTokenComment
)

type mfToken struct {
	kind mfTokenKind
	text string
	line int
	col  int // 1-based rune index within the line
}

var (
	mfGoVersionRE = regexp.MustCompile(`^([1-9][0-9]*)\.(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?([a-z0-9]+)?$`)
	mfVersionRE   = regexp.MustCompile(`^v(0|[1-9][0-9]*)(\.(0|[1-9][0-9]*))?(\.(0|[1-9][0-9]*))?((-[0-9A-Za-z\-.]+)?(\+[0-9A-Za-z\-.]+)?)?$`)
)

func mfIsVersion(s string) bool { return mfVersionRE.MatchString(s) }

func mfMajor(s string) string {
	if !mfIsVersion(s) {
		return ""
	}
	i := strings.IndexByte(s, '.')
	if i < 0 {
		return s[1:]
	}
	return s[1:i]
}

func mfValidVersion(v string) error {
	if !mfIsVersion(v) {
		return fmt.Errorf("version %q invalid: must be of the form v1.2.3", v)
	}
	if major := mfMajor(v); major != "0" && major != "1" {
		return fmt.Errorf("version %q invalid: should be v0 or v1, not %s", v, major)
	}
	return nil
}

// mfParseModule parses go.mod content and returns the module path.
func mfParseModule(filename string, data []byte) (string, error) {
	tokens, lexErr := mfLex(data)
	var errs mfErrorList
	if lexErr != nil {
		lexErr.Filename = filename
		errs = append(errs, lexErr)
	}

	moduleDefined := false
	goDefined := false
	modulePath := ""

	i := 0
	n := len(tokens)
	for i < n {
		tok := tokens[i]
		if tok.kind == mfTokenNewline || tok.kind == mfTokenComment || tok.kind == mfTokenEOF {
			i++
			continue
		}
		if tok.kind == mfTokenRParen {
			i++
			continue
		}
		if tok.kind == mfTokenLParen {
			// block start without a verb
			errs = append(errs, &mfError{Filename: filename, Pos: mfPos(tok), Err: fmt.Errorf("unknown directive: %s", tok.text)})
			end := mfSkipBlock(tokens, i)
			i = end
			continue
		}
		if tok.kind == mfTokenString {
			i++
			continue
		}

		verb := tok.text
		linePos := mfPos(tok)
		i++

		// gather the rest of the line
		var lineArgs []string
		for i < n {
			t := tokens[i]
			if t.kind == mfTokenNewline || t.kind == mfTokenComment || t.kind == mfTokenEOF {
				i++
				break
			}
			if t.kind == mfTokenRParen {
				i++
				break
			}
			lineArgs = append(lineArgs, t.text)
			i++
		}

		if strings.HasSuffix(verb, "(") {
			// e.g. "require(" -- the lexer keeps "(" glued to the word when
			// there is no space; split it off.
			verb = strings.TrimSuffix(verb, "(")
		}
		if len(lineArgs) > 0 && lineArgs[len(lineArgs)-1] == "(" {
			// block directive
			lineArgs = lineArgs[:len(lineArgs)-1]
			var blockArgs [][]string
			var blockStart int
			blockStart = i
			blockArgs, end := mfReadBlock(tokens, blockStart)
			i = end
			mfValidateBlock(&errs, filename, verb, lineArgs, blockArgs, linePos)
			continue
		}

		mfValidateLine(&errs, filename, verb, lineArgs, linePos, &moduleDefined, &goDefined, &modulePath)
	}

	if len(errs) > 0 {
		return "", errs
	}
	if !moduleDefined {
		return "", errors.New("module is undefined")
	}
	return modulePath, nil
}

func mfPos(t mfToken) mfPosition { return mfPosition{Line: t.line, LineRune: t.col} }

// mfReadBlock reads the lines of a parenthesized block starting after "(".
func mfReadBlock(tokens []mfToken, start int) ([][]string, int) {
	var result [][]string
	i := start
	n := len(tokens)
	cur := []string{}
	for i < n {
		tok := tokens[i]
		switch tok.kind {
		case mfTokenRParen:
			if len(cur) > 0 {
				result = append(result, cur)
			}
			return result, i + 1
		case mfTokenNewline, mfTokenComment:
			if len(cur) > 0 {
				result = append(result, cur)
				cur = nil
			}
		case mfTokenEOF:
			return nil, n
		case mfTokenLParen:
			return nil, n
		default:
			cur = append(cur, tok.text)
		}
		i++
	}
	return nil, n
}

func mfSkipBlock(tokens []mfToken, start int) int {
	i := start
	n := len(tokens)
	for i < n {
		if tokens[i].kind == mfTokenRParen {
