{"command": "cd /workspace && cat > cache.go <<'GOEOF'
package main

import (
	"crypto/md5"
	"encoding/hex"
	"os"
	"os/user"
	"path/filepath"
)

// cacheStore is a simple on-disk cache used with the -use-cache option.
// Keys are md5 hashes of the absolute file path, values are md5 hashes of the
// resulting (formatted) file content.
type cacheStore struct {
	dir string
}

func newCacheStore() *cacheStore {
	home := ""
	if u, err := user.Current(); err == nil {
		home = u.HomeDir
	}
	if home == "" {
		return &cacheStore{dir: ""}
	}
	return &cacheStore{dir: filepath.Join(home, ".cache", "goimports-reviser")}
}

func cacheKey(path string) string {
	sum := md5.Sum([]byte(path))
	return hex.EncodeToString(sum[:])
}

func (c *cacheStore) get(path string) (string, bool) {
	if c == nil || c.dir == "" {
		return "", false
	}
	data, err := os.ReadFile(filepath.Join(c.dir, cacheKey(path)))
	if err != nil {
		return "", false
	}
	return string(data), true
}

func (c *cacheStore) set(path, value string) {
	if c == nil || c.dir == "" {
		return
	}
	if err := os.MkdirAll(c.dir, 0o755); err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(c.dir, cacheKey(path)), []byte(value), 0o644)
}

func contentHash(data []byte) string {
	sum := md5.Sum(data)
	return hex.EncodeToString(sum[:])
}
GOEOF
