package main

// Minimal re-implementation of the package loading step (performed through the
// `go list` command) which is required for the "-rm-unused" and "-set-alias"
// options.

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
)

// goListPackage mirrors the subset of `go list -json` output which is used.
type goListPackage struct {
	ImportPath   string
	Name         string
	DepOnly      bool
	Imports      []string
	ImportMap    map[string]string
	TestImports  []string
	XTestImports []string
	Error        *goListError
}

// goListError mirrors go list's Error struct.
type goListError struct {
	ImportStack []string
	Pos         string
	Err         string
}

// Error implements the error interface with the same formatting used when
// printing package load errors.
func (e *goListError) Error() string {
	pos := e.Pos
	if pos == "" {
		pos = "-"
	}
	return pos + ": " + e.Err
}

type packageInfo struct {
	packages []*goListPackage
	byPath   map[string]*goListPackage
}

// runGo runs the go command in the given directory and returns stdout.
func runGo(dir string, env []string, args ...string) (string, error) {
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	cmd.Env = env
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		if ee, ok := err.(*exec.Error); ok {
			return "", fmt.Errorf("err: %v: stderr: %s",
				fmt.Errorf("go command required, not found: %v", ee), stderr.String())
		}
		return "", fmt.Errorf("err: %v: stderr: %s", err, stderr.String())
	}
	return stdout.String(), nil
}

// loadPackageInfo runs go list for the directory and parses the result.
func loadPackageInfo(dir string) (*packageInfo, error) {
	env := append([]string{}, os.Environ()...)
	env = append(env, "GO111MODULE=off")
	if _, err := runGo(dir, env, "list", "-e", "-f={{context.ReleaseTags}}", "--", "unsafe"); err != nil {
		return nil, err
	}

	stdout, err := runGo(dir, os.Environ(),
		"list", "-e", "-json=Name,ImportPath,Error,DepOnly,Imports,ImportMap,TestImports,XTestImports",
		"-compiled=false", "-test=true", "-export=false", "-deps=true", "-find=false", "-pgo=off", "--")
	if err != nil {
		return nil, err
	}

	info := &packageInfo{byPath: make(map[string]*goListPackage)}
	dec := json.NewDecoder(bytes.NewReader([]byte(stdout)))
	for dec.More() {
		var pkg goListPackage
		if err := dec.Decode(&pkg); err != nil {
			break
		}
		p := pkg
		info.packages = append(info.packages, &p)
		if _, ok := info.byPath[p.ImportPath]; !ok {
			info.byPath[p.ImportPath] = &p
		}
	}
	return info, nil
}

// errors returns all package errors in the order reported by go list.
func (info *packageInfo) errors() []*goListError {
	var out []*goListError
	for _, p := range info.packages {
		if p.Error != nil {
			out = append(out, p.Error)
		}
	}
	return out
}

// packageName returns the package name for the given import path, taking the
// import map of the package into account.
func (info *packageInfo) packageName(importPath string) string {
	if pkg, ok := info.byPath[importPath]; ok && pkg.Name != "" {
		return pkg.Name
	}
	for _, p := range info.packages {
		if mapped, ok := p.ImportMap[importPath]; ok {
			if pkg, ok := info.byPath[mapped]; ok && pkg.Name != "" {
				return pkg.Name
			}
		}
	}
	return ""
}

// hasErrors reports whether the loaded package set contains any error.
func (info *packageInfo) hasErrors() bool {
	for _, p := range info.packages {
		if p.Error != nil {
			return true
		}
	}
	return false
}
GOEOF
gofmt -l cache.go pkgload.go; echo ok"}

