{"command": "cd /workspace && cat > reviser.go <<'GOEOF'
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// groupKind identifies a logical group of imports.
type groupKind int

const (
	groupStd groupKind = iota
	groupGeneral
	groupCompany
	groupProject
	groupBlanked
	groupDotted
)

var groupByName = map[string]groupKind{
	"std":     groupStd,
	"general": groupGeneral,
	"company": groupCompany,
	"project": groupProject,
	"blanked": groupBlanked,
	"dotted":  groupDotted,
}

var defaultImportsOrder = []groupKind{groupStd, groupGeneral, groupCompany, groupProject}

var orderNames = map[groupKind]string{
	groupStd:     "std",
	groupGeneral: "general",
	groupCompany: "company",
	groupProject: "project",
	groupBlanked: "blanked",
	groupDotted:  "dotted",
}

// options holds all the command line options which affect the result.
type options struct {
	applyToGeneratedFiles bool
	companyPrefixes       []string
	format                bool
	order                 []groupKind
	listDiff              bool
	output                string
	recursive             bool
	rmUnused              bool
	separateNamed         bool
	setAlias              bool
	setExitStatus         bool
	useCache              bool
	cache                 *cacheStore
}

// importSpecInfo holds everything known about a single import spec.
type importSpecInfo struct {
	alias   string
	path    string
	comment string
	kind    groupKind
	hasName bool
}

// fix applies the imports revising (and optional formatting) to the file and
// returns the new content.
func (opts *options) fix(absPath string, projectName string) ([]byte, bool, error) {
	content, err := os.ReadFile(absPath)
	if err != nil {
		return nil, false, err
	}

	if opts.useCache && opts.cache != nil {
		if cached, ok := opts.cache.get(absPath); ok && cached == contentHash(content) {
			return nil, false, nil
		}
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, absPath, content, parser.ParseComments)
	if err != nil {
		if len(content) == 0 {
			return nil, false, fmt.Errorf("file is empty and cannot be parsed as Go source, use -excludes flag to skip this file: %v", err)
		}
		return nil, false, fmt.Errorf("file has invalid Go source content, use -excludes flag to skip this file: %v", err)
	}

	var pkgInfo *packageInfo
	if opts.rmUnused || opts.setAlias {
		pkgInfo, err = loadPackageInfo(filepath.Dir(absPath))
		if err != nil {
			return nil, false, err
		}
		if pkgInfo.hasErrors() {
			for _, e := range pkgInfo.errors() {
				fmt.Fprintln(os.Stderr, e.Error())
			}
			return nil, false, fmt.Errorf("package has an errors")
		}
	}

	if !opts.applyToGeneratedFiles && isGeneratedFile(f) {
		if opts.useCache && opts.cache != nil {
			opts.cache.set(absPath, contentHash(content))
		}
		return content, false, nil
	}

	src := string(content)

	// Collect the import declarations.
	var importDecls []*ast.GenDecl
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			importDecls = append(importDecls, gd)
		}
	}

	var regionStart, regionEnd int
	var specs []*importSpecInfo
	paren := false
	if len(importDecls) > 0 {
		first := importDecls[0]
		last := importDecls[len(importDecls)-1]
		for _, gd := range importDecls {
			if gd.Rparen.IsValid() {
				paren = true
			}
			for _, spec := range gd.Specs {
				if imp, ok := spec.(*ast.ImportSpec); ok {
					specs = append(specs, opts.makeImportSpecInfo(fset, imp, pkgInfo, projectName))
				}
			}
		}
		if len(specs) == 0 {
			// import block without specs: leave the region as is
			return opts.formatSource(fset, f, src, -1, -1)
		}
		lastSpec := last.Specs[len(last.Specs)-1].(*ast.ImportSpec)
		regionStart = int(first.Pos()) - 1
		regionEnd = int(lastSpec.End()) - 1
		if last.Rparen.IsValid() {
			regionEnd = int(last.Rparen) - 1
		} else if lastSpec.Comment != nil && len(lastSpec.Comment.List) > 0 {
			c := lastSpec.Comment.List[len(lastSpec.Comment.List)-1]
			if fset.Position(c.Pos()).Line == fset.Position(lastSpec.End()).Line {
				if int(c.Pos())-1 > regionEnd {
					// comment follows on the same line
					if int(c.Pos())-1 == regionEnd {
						// adjacent comment: include it into the region
						regionEnd = int(c.End()) - 1
					}
				}
			}
		}
	}

	// Remove unused imports.
	if opts.rmUnused && pkgInfo != nil {
		used := usedImports(fset, f, specs, pkgInfo)
		var kept []*importSpecInfo
		for i, s := range specs {
			if used[i] {
				kept = append(kept, s)
			}
		}
		specs = kept
	}

	if len(specs) == 0 {
		// nothing to import: drop the whole block
		regionStart = int(importDecls[0].Pos()) - 1
		if importDecls[0].Rparen.IsValid() {
			regionEnd = int(importDecls[0].Rparen)
		} else {
			regionEnd = int(importDecls[0].End())
		}
		// include the trailing newline of the block if it is followed by one
		if regionEnd < len(src) && src[regionEnd] == '\n' {
			regionEnd++
		}
		block := ""
		return opts.formatSource(fset, f, src, regionStart, regionEnd, block)
	}

	grouped := opts.groupImports(specs)
	block := renderImports(grouped, paren, opts.separateNamed, len(specs) == 1 && !paren)

	return opts.formatSource(fset, f, src, regionStart, regionEnd, block)
}

// makeImportSpecInfo builds the info for a single import spec.
func (opts *options) makeImportSpecInfo(fset *token.FileSet, imp *ast.ImportSpec, pkgInfo *packageInfo, projectName string) *importSpecInfo {
	path, _ := strconvUnquote(imp.Path.Value)
	info := &importSpecInfo{path: path}
	if imp.Name != nil {
		info.alias = imp.Name.Name
		info.hasName = true
	}
	if imp.Comment != nil && len(imp.Comment.List) > 0 {
		// Only comments which follow the spec on the same line are kept.
		var parts []string
		for _, c := range imp.Comment.List {
			if fset.Position(c.Pos()).Line != fset.Position(imp.End()).Line {
				continue
			}
			parts = append(parts, c.Text)
		}
		info.comment = strings.Join(parts, " ")
	}
	info.kind = opts.kindOf(info, projectName)
	return info
}

func strconvUnquote(s string) (string, error) {
	if len(s) >= 2 && s[0] == '"' {
		var b strings.Builder
		body := s[1 : len(s)-1]
		for i := 0; i < len(body); i++ {
			if body[i] == '\\' && i+1 < len(body) {
				i++
				switch body[i] {
				case 'n':
					b.WriteByte('\n')
				case 't':
					b.WriteByte('\t')
				case 'r':
					b.WriteByte('\r')
				case '"':
					b.WriteByte('"')
				case '\\':
					b.WriteByte('\\')
				default:
					b.WriteByte(body[i])
				}
				continue
			}
			b.WriteByte(body[i])
		}
		return b.String(), nil
	}
	if len(s) >= 2 && s[0] == '`' {
		return s[1 : len(s)-1], nil
	}
	return s, nil
}

// kindOf determines the group of the import spec.
func (opts *options) kindOf(info *importSpecInfo, projectName string) groupKind {
	if info.hasName && info.alias == "_" && opts.hasGroup(groupBlanked) {
		return groupBlanked
	}
	if info.hasName && info.alias == "." && opts.hasGroup(groupDotted) {
		return groupDotted
	}
	if projectName != "" && strings.HasPrefix(info.path, projectName) {
		return groupProject
	}
	for _, p := range opts.companyPrefixes {
		if p != "" && strings.HasPrefix(info.path, p) {
			return groupCompany
		}
	}
	if isStdPackage(info.path) {
		return groupStd
	}
	return groupGeneral
}

func (opts *options) hasGroup(k groupKind) bool {
	for _, g := range opts.order {
		if g == k {
			return true
		}
	}
	return false
}

// groupImports distributes the specs among the groups following the order.
func (opts *options) groupImports(specs []*importSpecInfo) [][]*importSpecInfo {
	buckets := make(map[groupKind][]*importSpecInfo)
	for _, s := range specs {
		buckets[s.kind] = append(buckets[s.kind], s)
	}
	var groups [][]*importSpecInfo
	for _, k := range opts.order {
		list := buckets[k]
		if len(list) == 0 {
			continue
		}
		sort.SliceStable(list, func(i, j int) bool { return list[i].path < list[j].path })
		groups = append(groups, list)
	}
	return groups
}

// renderImports builds the text of the new import block.
func renderImports(groups [][]*importSpecInfo, paren, separateNamed, numSpecs int) string {
	var b strings.Builder
	if numSpecs == 1 && !paren {
		// single import without parentheses
		b.WriteString("import ")
		writeSpec(&b, groups[0][0], false)
		return b.String()
	}
	b.WriteString("import (\n")
	for gi, g := range groups {
		if gi > 0 {
			b.WriteString("\n")
		}
		if separateNamed {
			var unnamed, named []*importSpecInfo
			for _, s := range g {
				if s.hasName {
					named = append(named, s)
				} else {
					unnamed = append(unnamed, s)
				}
			}
			for i, s := range unnamed {
				writeSpec(&b, s, true)
				if i < len(unnamed)-1 || len(named) > 0 {
					b.WriteString("\n")
				}
			}
			if len(unnamed) > 0 && len(named) > 0 {
				b.WriteString("\n")
			}
			for i, s := range named {
				writeSpec(&b, s, true)
				if i < len(named)-1 {
					b.WriteString("\n")
				}
			}
			continue
		}
		for i, s := range g {
			writeSpec(&b, s, true)
			if i < len(g)-1 {
				b.WriteString("\n")
			}
		}
	}
	b.WriteString("\n)")
	return b.String()
}

func writeSpec(b *strings.Builder, s *importSpecInfo, indent bool) {
	if indent {
		b.WriteString("\t")
	}
	if s.hasName {
		b.WriteString(s.alias)
		b.WriteString(" ")
	}
	b.WriteString("\"")
	b.WriteString(s.path)
	b.WriteString("\"")
	if s.comment != "" {
		b.WriteString(" ")
		b.WriteString(s.comment)
	}
	b.WriteString("\t")
}

// formatSource applies the -format blank line insertion (if requested) and
// gofmt to the result. regionStart/regionEnd are byte offsets in src of the
// replaced import region; block is the new import block text.
func (opts *options) formatSource(fset *token.FileSet, f *ast.File, src string, regionStart, regionEnd int, block string) ([]byte, error) {
	var b strings.Builder
	if regionStart < 0 {
		// no import region
		b.WriteString(src)
	} else {
		b.WriteString(src[:regionStart])
		b.WriteString(block)
		b.WriteString("\t")
		if regionEnd <= len(src) {
			b.WriteString(src[regionEnd:])
		}
	}

	result := b.String()

	if opts.format {
		result = opts.separateDecls(fset, f, src, result, regionStart, regionEnd)
	}

	formatted, err := format.Source([]byte(result))
	if err != nil {
		return []byte(result), nil
	}
	return formatted, nil
}

// separateDecls inserts blank lines between the top-level declarations.
func (opts *options) separateDecls(fset *token.FileSet, f *ast.File, src, result string, regionStart, regionEnd int) string {
	var decls []ast.Decl
	for _, d := range f.Decls {
		if gd, ok := d.(*ast.GenDecl); ok && gd.Tok == token.IMPORT {
			continue
		}
		decls = append(decls, d)
	}
	if len(decls) == 0 {
		return result
	}

	// compute the offsets relative to the beginning of the suffix part
	offset := regionEnd
	if regionStart < 0 {
		offset = 0
	}
	type insertion struct {
		pos  int
		text string
	}
	var ins []insertion
	for i := 1; i < len(decls); i++ {
		prev := decls[i-1]
		cur := decls[i]
		if hasCommentOnLine(fset, f, fset.Position(prev.End()).Line) {
			continue
		}
		start := cur.Pos()
		if curDoc := declDoc(cur); curDoc != nil && curDoc.Pos() < start {
			start = curDoc.Pos()
		}
		off := int(start) - 1 - offset
		if off < 0 {
			continue
		}
		ins = append(ins, insertion{pos: off, text: "\n"})
	}
	if len(ins) == 0 {
		return result
	}
	// apply the insertions from the end
	out := result
	for i := len(ins) - 1; i >= 0; i-- {
		pos := ins[i].pos
		if pos > len(out) {
			continue
		}
		out = out[:pos] + ins[i].text + out[pos:]
	}
	return out
}

func declDoc(d ast.Decl) *ast.CommentGroup {
	switch n := d.(type) {
	case *ast.FuncDecl:
		return n.Doc
	case *ast.GenDecl:
		return n.Doc
	}
	return nil
}

// hasCommentOnLine reports whether any comment group starts on the given line.
func hasCommentOnLine(fset *token.FileSet, f *ast.File, line int) bool {
	for _, cg := range f.Comments {
		if fset.Position(cg.Pos()).Line == line {
			return true
		}
	}
	return false
}

// isGeneratedFile reports whether the file starts with a "// Code generated"
// comment (as defined by the go tool conventions).
func isGeneratedFile(f *ast.File) bool {
	if len(f.Comments) == 0 {
		return false
	}
	for _, c := range f.Comments[0].List {
		if generatedRE.MatchString(c.Text) {
			return true
		}
	}
	return false
}

