		data, err := os.ReadFile(filepath.Join(dir, "go.mod"))
		if err == nil {
			return mfParseModule("go.mod", data)
		}
		parent := filepath.Dir(dir)
		if parent == dir || dir == "." {
			return "", err
		}
		dir = parent
	}
