{"command": "cd /workspace && cat > scope.go <<'GOEOF'
package main

// Scope aware resolution of identifier uses, used to detect imports which are
// not referenced anywhere in the file ("-rm-unused" option).

import (
	"go/ast"
	"go/token"
	"strings"
)

// scope is a lexical scope holding declarations.
type scope struct {
	parent  *scope
	entries map[string]int // import index, or -1 for a non-import declaration
}

func newScope(parent *scope) *scope {
	return &scope{parent: parent, entries: make(map[string]int)}
}

func (s *scope) lookup(name string) (int, bool) {
	for sc := s; sc != nil; sc = sc.parent {
		if v, ok := sc.entries[name]; ok {
			return v, true
		}
	}
	return -1, false
}

func (s *scope) declare(name string, idx int) {
	if name == "" {
		return
	}
	s.entries[name] = idx
}

// importName returns the identifier which refers to the import inside the file.
func importName(s *importSpecInfo, pkgInfo *packageInfo) string {
	if s.hasName {
		return s.alias
	}
	if pkgInfo != nil {
		if name := pkgInfo.packageName(s.path); name != "" {
			return name
		}
	}
	i := strings.LastIndexByte(s.path, '/')
	if i < 0 {
		return s.path
	}
	return s.path[i+1:]
}

// usedImports reports which of the import specs are used in the file.
func usedImports(fset *token.FileSet, f *ast.File, specs []*importSpecInfo, pkgInfo *packageInfo) []bool {
	used := make([]bool, len(specs))
	root := newScope(nil)
	for i, s := range specs {
		name := importName(s, pkgInfo)
		if name == "" {
			continue
		}
		root.declare(name, i)
	}
	for _, d := range f.Decls {
		declareTopLevel(root, d)
	}
	for _, d := range f.Decls {
		walkNode(d, root, used)
	}
	return used
}

func declareTopLevel(s *scope, d ast.Decl) {
	switch x := d.(type) {
	case *ast.FuncDecl:
		if x.Name != nil {
			s.declare(x.Name.Name, -1)
		}
	case *ast.GenDecl:
		for _, spec := range x.Specs {
			switch sp := spec.(type) {
			case *ast.ValueSpec:
				for _, name := range sp.Names {
					s.declare(name.Name, -1)
				}
			case *ast.TypeSpec:
				s.declare(sp.Name.Name, -1)
			}
		}
	}
}

func walkNode(n ast.Node, s *scope, used []bool) {
	switch x := n.(type) {
	case nil:
		return
	case *ast.Ident:
		if idx, ok := s.lookup(x.Name); ok && idx >= 0 {
			used[idx] = true
		}
	case *ast.BasicLit, *ast.BadDecl, *ast.BadExpr, *ast.BadStmt, *ast.EmptyStmt, *ast.BranchStmt:
		return
	case *ast.File:
		for _, d := range x.Decls {
			walkNode(d, s, used)
		}
	case *ast.GenDecl:
		for _, spec := range x.Specs {
			walkNode(spec, s, used)
		}
	case *ast.ImportSpec:
		return
	case *ast.ValueSpec:
		for _, name := range x.Names {
			s.declare(name.Name, -1)
		}
		if x.Type != nil {
			walkNode(x.Type, s, used)
		}
		for _, v := range x.Values {
			walkNode(v, s, used)
		}
	case *ast.TypeSpec:
		s.declare(x.Name.Name, -1)
		sc := s
		if x.TypeParams != nil {
			sc = newScope(s)
			walkDeclFieldList(x.TypeParams, sc, used)
		}
		walkNode(x.Type, sc, used)
	case *ast.FuncDecl:
		funcScope := newScope(s)
		if x.Recv != nil {
			walkDeclFieldList(x.Recv, funcScope, used)
		}
		walkFuncType(x.Type, funcScope, used)
		if x.Body != nil {
			bodyScope := newScope(funcScope)
			for _, st := range x.Body.List {
				walkNode(st, bodyScope, used)
			}
		}
	case *ast.FuncLit:
		funcScope := newScope(s)
		walkFuncType(x.Type, funcScope, used)
		if x.Body != nil {
			bodyScope := newScope(funcScope)
			for _, st := range x.Body.List {
				walkNode(st, bodyScope, used)
			}
		}
	case *ast.StructType:
		for _, field := range x.Fields.List {
			walkNode(field.Type, s, used)
		}
	case *ast.InterfaceType:
		for _, method := range x.Methods.List {
			walkNode(method.Type, s, used)
		}
	case *ast.ArrayType:
		if x.Len != nil {
			walkNode(x.Len, s, used)
		}
		walkNode(x.Elt, s, used)
	case *ast.MapType:
		walkNode(x.Key, s, used)
		walkNode(x.Value, s, used)
	case *ast.ChanType:
		walkNode(x.Value, s, used)
	case *ast.Ellipsis:
		walkNode(x.Elt, s, used)
	case *ast.ParenExpr:
		walkNode(x.X, s, used)
	case *ast.StarExpr:
		walkNode(x.X, s, used)
	case *ast.UnaryExpr:
		walkNode(x.X, s, used)
	case *ast.BinaryExpr:
		walkNode(x.X, s, used)
		walkNode(x.Y, s, used)
	case *ast.CallExpr:
		walkNode(x.Fun, s, used)
		for _, arg := range x.Args {
			walkNode(arg, s, used)
		}
	case *ast.CompositeLit:
		if x.Type != nil {
			walkNode(x.Type, s, used)
		}
		for _, e := range x.Elts {
			if kv, ok := e.(*ast.KeyValueExpr); ok {
				walkNode(kv.Key, s, used)
				walkNode(kv.Value, s, used)
				continue
			}
			walkNode(e, s, used)
		}
	case *ast.KeyValueExpr:
		walkNode(x.Key, s, used)
		walkNode(x.Value, s, used)
	case *ast.IndexExpr:
		walkNode(x.X, s, used)
		walkNode(x.Index, s, used)
	case *ast.IndexListExpr:
		walkNode(x.X, s, used)
		for _, idx := range x.Indices {
			walkNode(idx, s, used)
		}
	case *ast.SelectorExpr:
		walkNode(x.X, s, used)
	case *ast.SliceExpr:
		walkNode(x.X, s, used)
		if x.Low != nil {
			walkNode(x.Low, s, used)
		}
		if x.High != nil {
			walkNode(x.High, s, used)
		}
		if x.Max != nil {
			walkNode(x.Max, s, used)
		}
	case *ast.TypeAssertExpr:
		walkNode(x.X, s, used)
		if x.Type != nil {
			walkNode(x.Type, s, used)
		}
	case *ast.DeclStmt:
		walkNode(x.Decl, s, used)
	case *ast.AssignStmt:
		for _, lhs := range x.Lhs {
			if ident, ok := lhs.(*ast.Ident); ok && x.Tok == token.DEFINE {
				s.declare(ident.Name, -1)
				continue
			}
			walkNode(lhs, s, used)
		}
		for _, rhs := range x.Rhs {
			walkNode(rhs, s, used)
		}
	case *ast.IncDecStmt:
		walkNode(x.X, s, used)
	case *ast.SendStmt:
		walkNode(x.Chan, s, used)
		walkNode(x.Value, s, used)
	case *ast.ExprStmt:
		walkNode(x.X, s, used)
	case *ast.GoStmt:
		walkNode(x.Call, s, used)
	case *ast.DeferStmt:
		walkNode(x.Call, s, used)
	case *ast.ReturnStmt:
		for _, res := range x.Results {
			walkNode(res, s, used)
		}
	case *ast.BlockStmt:
		bs := newScope(s)
		for _, st := range x.List {
			walkNode(st, bs, used)
		}
	case *ast.IfStmt:
		is := newScope(s)
		if x.Init != nil {
			walkNode(x.Init, is, used)
		}
		if x.Cond != nil {
			walkNode(x.Cond, is, used)
		}
		walkNode(x.Body, is, used)
		if x.Else != nil {
			walkNode(x.Else, is, used)
		}
	case *ast.ForStmt:
		fs := newScope(s)
		if x.Init != nil {
			walkNode(x.Init, fs, used)
		}
		if x.Cond != nil {
			walkNode(x.Cond, fs, used)
		}
		if x.Post != nil {
			walkNode(x.Post, fs, used)
		}
		walkNode(x.Body, fs, used)
	case *ast.RangeStmt:
		rs := newScope(s)
		if x.Key != nil {
			if ident, ok := x.Key.(*ast.Ident); ok && x.Tok == token.DEFINE {
				rs.declare(ident.Name, -1)
			} else {
				walkNode(x.Key, rs, used)
			}
		}
		if x.Value != nil {
			if ident, ok := x.Value.(*ast.Ident); ok && x.Tok == token.DEFINE {
				rs.declare(ident.Name, -1)
			} else {
				walkNode(x.Value, rs, used)
			}
		}
		walkNode(x.X, rs, used)
		walkNode(x.Body, rs, used)
	case *ast.SwitchStmt:
		ss := newScope(s)
		if x.Init != nil {
			walkNode(x.Init, ss, used)
		}
		if x.Tag != nil {
			walkNode(x.Tag, ss, used)
		}
		for _, c := range x.Body.List {
			walkNode(c, ss, used)
		}
	case *ast.CaseClause:
		cs := newScope(s)
		for _, e := range x.List {
			walkNode(e, cs, used)
		}
		for _, st := range x.Body {
			walkNode(st, cs, used)
		}
	case *ast.TypeSwitchStmt:
		ts := newScope(s)
		if x.Init != nil {
			walkNode(x.Init, ts, used)
		}
		walkNode(x.Assign, ts, used)
		for _, c := range x.Body.List {
			walkNode(c, ts, used)
		}
	case *ast.SelectStmt:
		sel := newScope(s)
		for _, c := range x.Body.List {
			walkNode(c, sel, used)
		}
	case *ast.CommClause:
		cs := newScope(s)
		if x.Comm != nil {
			walkNode(x.Comm, cs, used)
		}
		for _, st := range x.Body {
			walkNode(st, cs, used)
		}
	case *ast.LabeledStmt:
		walkNode(x.Stmt, s, used)
	default:
		// walk the children generically
		walkChildren(n, s, used)
	}
}

// walkChildren walks all the children of a node which is not handled
// explicitly (defensive fallback).
func walkChildren(n ast.Node, s *scope, used []bool) {
	ast.Inspect(n, func(node ast.Node) bool {
		if node == n {
			return true
		}
		switch node.(type) {
		case *ast.Ident:
			if idx, ok := s.lookup(node.(*ast.Ident).Name); ok && idx >= 0 {
				used[idx] = true
			}
			return false
		}
		return true
	})
}

func walkFuncType(t *ast.FuncType, s *scope, used []bool) {
	if t == nil {
		return
	}
	if t.TypeParams != nil {
		walkDeclFieldList(t.TypeParams, s, used)
	}
	if t.Params != nil {
		walkDeclFieldList(t.Params, s, used)
	}
	if t.Results != nil {
		walkDeclFieldList(t.Results, s, used)
	}
}

// walkDeclFieldList declares the field names and walks the types.
func walkDeclFieldList(fl *ast.FieldList, s *scope, used []bool) {
	if fl == nil {
		return
	}
	for _, field := range fl.List {
		for _, name := range field.Names {
			s.declare(name.Name, -1)
		}
		walkNode(field.Type, s, used)
	}
}
