// parseImportsOrder validates the -imports-order option value.
func parseImportsOrder(value string) ([]groupKind, error) {
	if value == "" {
		return append([]groupKind{}, defaultImportsOrder...), nil
	}
	parts := strings.Split(value, ",")
	order := make([]groupKind, 0, len(parts))
	for _, p := range parts {
		name := strings.TrimSpace(p)
		kind, ok := groupByName[name]
		if !ok {
			return nil, fmt.Errorf("unknown order group type: %q", name)
		}
		order = append(order, kind)
	}
	if len(order) < 4 {
		return nil, fmt.Errorf("use default at least 4 parameters to sort groups of your imports: %q", defaultOrderString)
	}
	return order, nil
}

// parseCompanyPrefixes splits the -company-prefixes option value.
func parseCompanyPrefixes(value string) []string {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	var result []string
	for _, p := range strings.Split(value, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			return nil
		}
		result = append(result, p)
	}
	return result
}

// processPath handles a single command line target.
func processPath(path string, opts *options, exitStatus *int) error {
	log.Println("Processing", path)

	projectName, err := getProjectName(path, projectName)
	if err != nil {
		flag.Usage()
		log.Fatalf("Could not determine project name for path %s: %v", path, err)
	}

	if path == "./..." {
		return walkDir(".", opts, projectName)
	}

	info, err := os.Stat(path)
	if err != nil || !info.IsDir() {
		return fixSingleFile(path, opts, projectName, exitStatus)
	}
	return walkDir(path, opts, projectName)
}

// fixSingleFile processes a single .go file.
func fixSingleFile(path string, opts *options, projectName string, exitStatus *int) error {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return err
	}
	newContent, changed, err := opts.fix(absPath, projectName)
	if err != nil {
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}
	if opts.listDiff {
		fmt.Println(absPath)
	}
	if opts.output == "stdout" && newContent != nil {
		fmt.Println(string(newContent))
	}
	if newContent == nil {
		return nil
	}
	if err := os.WriteFile(absPath, newContent, 0o644); err != nil {
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}
	if opts.useCache && opts.cache != nil {
		opts.cache.set(absPath, contentHash(newContent))
	}
	if changed && opts.setExitStatus {
		*exitStatus = 1
	}
	return nil
}
