package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

const (
	appVersion = "3.0.0-20260611193416-a37f51062178"
	builtWith  = "go1.26.0"
	tagName    = "v3.0.0-20260611193416-a37f51062178"
	commitHash = "n/a"
	sourceRepo = "github.com/incu6us/goimports-reviser/v3"
)

var defaultOrderString = "std,general,company,project"

var (
	applyToGeneratedFiles bool
	companyPrefixes       string
	excludes              string
	filePath              string
	format                bool
	importsOrder          string
	listDiff              bool
	local                 string
	output                string
	projectName           string
	recursive             bool
	rmUnused              bool
	separateNamed         bool
	setAlias              bool
	setExitStatus         bool
	useCache              bool
	showVersion           bool
	showVersionOnly       bool
)

func init() {
	flag.BoolVar(&applyToGeneratedFiles, "apply-to-generated-files", false,
		"Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&companyPrefixes, "company-prefixes", "",
		"Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&excludes, "excludes", "",
		"Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&filePath, "file-path", "",
		"Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&format, "format", false,
		"Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&importsOrder, "imports-order", defaultOrderString,
		"Your imports groups can be sorted in your way. \n"+
			"std - std import group; \n"+
			"general - libs for general purpose; \n"+
			"company - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \n"+
			"project - your local project dependencies;\n"+
			"blanked - imports with \"_\" alias;\n"+
			"dotted - imports with \".\" alias.\n"+
			"Optional parameter.")
	flag.BoolVar(&listDiff, "list-diff", false,
		"Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&local, "local", "", "Deprecated")
	flag.StringVar(&output, "output", "file",
		"Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&projectName, "project-name", "",
		"Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&recursive, "recursive", false,
		"Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&rmUnused, "rm-unused", false,
		"Remove unused imports. Optional parameter.")
	flag.BoolVar(&separateNamed, "separate-named", false,
		"Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&setAlias, "set-alias", false,
		"Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&setExitStatus, "set-exit-status", false,
		"set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&useCache, "use-cache", false,
		"Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&showVersion, "version", false, "Show version information")
	flag.BoolVar(&showVersionOnly, "version-only", false, "Show only the version string")
}

func main() {
	flag.Parse()

	if showVersionOnly {
		fmt.Println(appVersion)
		return
	}
	if showVersion {
		fmt.Printf("version: %s\nbuilt with: %s\ntag: %s\ncommit: %s\nsource: %s\n",
			appVersion, builtWith, tagName, commitHash, sourceRepo)
		return
	}

	paths := flag.Args()
	if filePath != "" {
		paths = append(paths, filePath)
	}
	if len(paths) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	order, orderErr := parseImportsOrder(importsOrder)
	if orderErr != nil {
		flag.Usage()
		log.Println(orderErr)
		return
	}

	opts := &options{
		applyToGeneratedFiles: applyToGeneratedFiles,
		companyPrefixes:       parseCompanyPrefixes(companyPrefixes),
		format:                format,
		order:                 order,
		listDiff:              listDiff,
		output:                output,
		recursive:             recursive,
		rmUnused:              rmUnused,
		separateNamed:         separateNamed,
		setAlias:              setAlias,
		setExitStatus:         setExitStatus,
		useCache:              useCache,
	}
	if opts.output != "file" && opts.output != "write" && opts.output != "stdout" {
		log.Printf("invalid output %q specified", opts.output)
		os.Exit(1)
	}
	if opts.useCache {
		opts.cache = newCacheStore()
	}

	var exitStatus int
	for _, path := range paths {
		if err := processPath(path, opts, &exitStatus); err != nil {
			log.Fatal(err)
		}
	}

	if local != "" {
		log.Println("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Println("All changes to file are applied, but command-line syntax should be fixed")
	}

	if exitStatus != 0 {
		os.Exit(exitStatus)
	}
}

// parseImportsOrder validates the -imports-order option value.
func parseImportsOrder(value string) ([]groupKind, error) {
	if value == "" {
		return append([]groupKind{}, defaultImportsOrder...), nil
	}
	parts := strings.Split(value, ",")
	order := make([]groupKind, 0, len(parts))
	for _, p := range parts {
		name := strings.TrimSpace(p)
		kind, ok := groupByName[name]
		if !ok {
			return nil, fmt.Errorf("unknown order group type: %q", name)
		}
		order = append(order, kind)
	}
	if len(order) < 4 {
		return nil, fmt.Errorf("use default at least 4 parameters to sort groups of your imports: %q", defaultOrderString)
	}
	return order, nil
}

// parseCompanyPrefixes splits the -company-prefixes option value.
func parseCompanyPrefixes(value string) []string {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	var result []string
	for _, p := range strings.Split(value, ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			return nil
		}
		result = append(result, p)
	}
	return result
}

// processPath handles a single command line target.
func processPath(path string, opts *options, exitStatus *int) error {
	log.Println("Processing", path)

	projectName, err := getProjectName(path, projectName)
	if err != nil {
		flag.Usage()
		log.Fatalf("Could not determine project name for path %s: %v", path, err)
	}

	if path == "./..." {
		return walkDir(".", opts, projectName)
	}

	info, err := os.Stat(path)
	if err != nil || !info.IsDir() {
		return fixSingleFile(path, opts, projectName, exitStatus)
	}
	return walkDir(path, opts, projectName)
}

// fixSingleFile processes a single .go file.
func fixSingleFile(path string, opts *options, projectName string, exitStatus *int) error {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return err
	}
	newContent, changed, err := opts.fix(absPath, projectName)
	if err != nil {
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}
	if opts.listDiff {
		fmt.Println(absPath)
	}
	if opts.output == "stdout" && newContent != nil {
		fmt.Println(string(newContent))
	}
	if newContent == nil {
		return nil
	}
	if err := os.WriteFile(absPath, newContent, 0o644); err != nil {
		log.Printf("Failed to fix file: %v", err)
		os.Exit(1)
	}
	if opts.useCache && opts.cache != nil {
		opts.cache.set(absPath, contentHash(newContent))
	}
	if changed && opts.setExitStatus {
		*exitStatus = 1
	}
	return nil
}
